import{_ as i,o as a,c as e,a4 as t}from"./chunks/framework.DzJZdBQK.js";const d=JSON.parse('{"title":"CORS 跨域资源共享","description":"","frontmatter":{"date":"2018-05-12T11:09:50","title":"CORS 跨域资源共享","categories":["frontend","security"],"tags":["CORS"]},"headers":[{"level":2,"title":"同源判断规则","slug":"同源判断规则","link":"#同源判断规则","children":[]},{"level":2,"title":"CORS工作机制","slug":"cors工作机制","link":"#cors工作机制","children":[]},{"level":2,"title":"CORS相关消息头","slug":"cors相关消息头","link":"#cors相关消息头","children":[{"level":3,"title":"请求头","slug":"请求头","link":"#请求头","children":[]},{"level":3,"title":"响应头","slug":"响应头","link":"#响应头","children":[]}]}],"relativePath":"posts/frontend/security/cors.md","filePath":"posts/frontend/security/cors.md"}'),l={name:"posts/frontend/security/cors.md"};function n(h,s,r,o,p,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h1><p>因为使用Angular来调用ipfs的API时出现403禁止访问错误，首先判断的是跨域问题，尝试如下内容：直接在浏览器中输入URL访问可以，通过代理或浏览器的允许跨域设置依然是403错误。 通过查看ipfs的文档（<a href="https://github.com/ipfs/js-ipfs-api%EF%BC%89%EF%BC%8CIPFS%E6%9C%8D%E5%8A%A1%E5%99%A8%E9%BB%98%E8%AE%A4%E4%B8%8D%E6%94%AF%E6%8C%81%E8%B7%A8%E5%9F%9F%E8%AF%B7%E6%B1%82%EF%BC%8C%E9%9C%80%E8%A6%81%E4%BF%AE%E6%94%B9%E9%85%8D%E7%BD%AE%E6%96%87%E4%BB%B6%E3%80%82" target="_blank" rel="noreferrer">https://github.com/ipfs/js-ipfs-api），IPFS服务器默认不支持跨域请求，需要修改配置文件。</a></p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ipfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API.HTTPHeaders.Access-Control-Allow-Origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ipfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API.HTTPHeaders.Access-Control-Allow-Credentials</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ipfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API.HTTPHeaders.Access-Control-Allow-Methods</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]&quot;</span></span></code></pre></div><p>修改配置，重启IPFS之后正常访问IPFS的API。</p><h1 id="分析" tabindex="-1">分析 <a class="header-anchor" href="#分析" aria-label="Permalink to &quot;分析&quot;">​</a></h1><p>对于CORS没有理解，通过查看Wiki整理下对CORS，加深理解。为什么浏览器中可以访问而前端调用不行？ 直接在浏览器中可以直接访问是因为他是第一下资源地址，是一个GET请求，不是跨域请求。 Angular中请求时，是一个XHR请求，且与第一个资源地址不同，是跨域请求。</p><h1 id="跨域资源共享" tabindex="-1">跨域资源共享 <a class="header-anchor" href="#跨域资源共享" aria-label="Permalink to &quot;跨域资源共享&quot;">​</a></h1><p>跨域资源共享是一种机制，它允许受限的访问第一个访问资源域以外的资源（如字体）的机制。一张网页通常包含了很多跨域的图片，样式，脚本，iframes，或者视频。一些跨域请求，尤其是Ajax请求，会因为默认的<a href="https://en.wikipedia.org/wiki/Same-origin_policy" target="_blank" rel="noreferrer">同源安全策略</a>而被禁止访问。</p><p>CORS定义了浏览器和服务器如何来决定一个跨域请求是安全的。它比完全同源请求有更多的自由和功能，但不要只是简单地允许所有跨源请求。CORS规范最初是作为W3C推荐标准发布的，但该文档已经过时。 <a href="https://fetch.spec.whatwg.org/" target="_blank" rel="noreferrer">Fetch Living Standard</a>是当前维护活跃的规范。</p><h2 id="同源判断规则" tabindex="-1">同源判断规则 <a class="header-anchor" href="#同源判断规则" aria-label="Permalink to &quot;同源判断规则&quot;">​</a></h2><p>绝对路径，需要是协议，域名，端口号三者与第一个访问的资源（浏览器中输入的URL）相同，才被认为是同源。</p><h2 id="cors工作机制" tabindex="-1">CORS工作机制 <a class="header-anchor" href="#cors工作机制" aria-label="Permalink to &quot;CORS工作机制&quot;">​</a></h2><p>CORS标准新增了一组HTTP消息头，它为浏览器和服务器之间提供了一种有权限时才请求远程URL的方法。虽然服务器可以执行一些验证和授权，但浏览器通常有责任支持这些消息头并执行相关限制。</p><p>对于可以修改数据的Ajax和HTTP请求方法(通常是GET以外的HTTP方法，或者用于某些MIME类型的POST使用)，规范要求浏览器“预先执行”请求，使用HTTP的OPTIONS方法从服务器请求受支持的方法，然后在服务器“批准”后，使用实际的HTTP请求方法发送实际请求。服务器还可以通知客户端是否应该通过请求发送“凭据”(包括Cookies和HTTP身份验证数据)。 <a href="https://en.wikipedia.org/wiki/File:Flowchart_showing_Simple_and_Preflight_XHR.svg" target="_blank" rel="noreferrer">cors</a></p><h2 id="cors相关消息头" tabindex="-1">CORS相关消息头 <a class="header-anchor" href="#cors相关消息头" aria-label="Permalink to &quot;CORS相关消息头&quot;">​</a></h2><h3 id="请求头" tabindex="-1">请求头 <a class="header-anchor" href="#请求头" aria-label="Permalink to &quot;请求头&quot;">​</a></h3><ul><li>Origin</li><li>Access-Control-Request-Method</li><li>Access-Control-Request-Headers</li></ul><h3 id="响应头" tabindex="-1">响应头 <a class="header-anchor" href="#响应头" aria-label="Permalink to &quot;响应头&quot;">​</a></h3><ul><li>Access-Control-Allow-Origin</li><li>Access-Control-Allow-Credentials</li><li>Access-Control-Expose-Headers</li><li>Access-Control-Max-Age</li><li>Access-Control-Allow-Methods</li><li>Access-Control-Allow-Headers</li></ul><p>Access-Control-Allow-Origin: *</p><p>“*”的值是特殊的，因为它不允许请求提供凭据，这意味着不允许发送HTTP身份验证、客户端SSL证书和Cookie等原因。</p>`,21)])])}const c=i(l,[["render",n]]);export{d as __pageData,c as default};
